    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or seen[r][c]:
                continue

            stack = [(r, c)]
            seen[r][c] = True
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            not seen[ny][nx] and grid[ny][nx] == color):
                        seen[ny][nx] = True
                        stack.append((ny, nx))

            r0 = min(y for y, x in cells)
            r1 = max(y for y, x in cells)
            c0 = min(x for y, x in cells)
            c1 = max(x for y, x in cells)

            # Filled rectangular components are the tile interiors.
            if len(cells) == (r1 - r0 + 1) * (c1 - c0 + 1):
                components.append((r0, r1, c0, c1, color))

    if not components:
        return out

    # Interior patches share a common size. This also excludes solid scraps
    # from any clipped border tiles at the grid edge.
    shape_counts = Counter(
        (r1 - r0 + 1, c1 - c0 + 1)
        for r0, r1, c0, c1, _ in components
    )
    patch_shape = shape_counts.most_common(1)[0][0]
    patches = [
        p for p in components
        if (p[1] - p[0] + 1, p[3] - p[2] + 1) == patch_shape
    ]

    # The most frequent patch color is the ordinary color; connect the
    # matching patches of the other colors.
    ordinary = Counter(p[4] for p in patches).most_common(1)[0][0]
    patches = [p for p in patches if p[4] != ordinary]

    for i, (r0, r1, c0, c1, color) in enumerate(patches):
        for a0, a1, b0, b1, other in patches[i + 1:]:
            if color != other:
                continue

            if r0 == a0 and r1 == a1:
                left, right = sorted((c0, b0))
                for y in range(r0, r1 + 1):
                    for x in range(left + (c1 - c0 + 1), right):
                        if grid[y][x] == 0:
                            out[y][x] = color

            if c0 == b0 and c1 == b1:
                top, bottom = sorted((r0, a0))
                for x in range(c0, c1 + 1):
                    for y in range(top + (r1 - r0 + 1), bottom):
                        if grid[y][x] == 0:
                            out[y][x] = color

    return out
